fn only_ffi_graphic_names_the_graphic_crate() {
    let root = std::path::Path::new(concat!(env!("CARGO_MANIFEST_DIR"), "/src"));
    // Every `.rs` file under `core/src`, module directories included.
    let mut files: Vec<std::path::PathBuf> = Vec::new();
    let mut pending = vec![root.to_path_buf()];
    while let Some(dir) = pending.pop() {
        for entry in fs::read_dir(&dir).expect("a source directory") {
            let path = entry.expect("an entry").path();
            if path.is_dir() {
                pending.push(path);
            } else if path.extension().is_some_and(|e| e == "rs") {
                files.push(path);
            }
        }
    }
    let mut naming: Vec<String> = Vec::new();
    for path in files {
        let text = fs::read_to_string(&path).expect("a source file");
        let names = text.lines().any(|line| {
            line.trim_start().starts_with("use graphic")
                || line.match_indices("graphic::").any(|(i, _)| {
                    i == 0
                        || !line.as_bytes()[i - 1].is_ascii_alphanumeric()
                            && line.as_bytes()[i - 1] != b'_'
                })
        });
        if names {
            let relative = path.strip_prefix(root).expect("under core/src");
            naming.push(relative.to_string_lossy().into_owned());
        }
    }
    naming.sort();
    assert_eq!(naming, vec!["ffi_graphic.rs".to_string()]);
}

#[test]
fn one_max_side_in_the_engine_the_core_and_the_header() {
    // G-2 keeps `graphic` out of `model_graphic.rs`, so the core restates the
    // engine's side cap, and the app reads the header's `#define`; this is
    // the one place the three are compared.
    assert_eq!(
        graphic::MAX_SIDE,
        framejob_core::model_graphic::GRAPHIC_MAX_SIDE
    );
    let header = include_str!("../include/framejob_core.h");
    let stated = header
        .lines()
            height: 0,
            r#in: 0,
            length: None,
            props: Map::new(),
        }
    }
}

/// G-3's rule, `^[a-z0-9][a-z0-9-]{0,62}$`: safe on disk, in a URL, in a tool.
pub(crate) fn check_name(name: &str) -> Result<(), String> {
    let mut chars = name.chars();
    let head = chars
        .next()
        .is_some_and(|c| c.is_ascii_lowercase() || c.is_ascii_digit());
    let rest = chars.all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-');
    if head && rest && name.len() <= 63 {
        Ok(())
    } else {
        Err(format!("graphic name \"{name}\" {NAME_RULE}"))
    }
}

